#!/usr/bin/env node
// DEVELOPMENT-TIME tool (ADR 0007). Turns audio generated by a locally run AI model (see generate.py) into a
// VoxStudio unit database. Nothing in this directory is part of the application or its Docker image.
// Usage: node tools/data-gen/build-from-generated.mjs <generatedDir> <outDbDir> [--id vi-north-vieneu] [--version 1]
// generatedDir contains: units.json [{ id, label, variant, text }], audio/<id>.wav (mono 22,050 Hz PCM16), generator.json.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import core from '../../packages/core/dist/index.js';

const arg = (n, d) => (process.argv.includes(n) ? process.argv[process.argv.indexOf(n) + 1] : d);
const [genDir, outDir] = process.argv
  .slice(2)
  .filter((a, i, all) => !a.startsWith('--') && !all[i - 1]?.startsWith('--'));
if (!genDir || !outDir) {
  console.error(
    'usage: node tools/data-gen/build-from-generated.mjs <generatedDir> <outDbDir> [--id x] [--version n]',
  );
  process.exit(2);
}
const gen = JSON.parse(readFileSync(path.join(genDir, 'generator.json'), 'utf8'));
const units = JSON.parse(readFileSync(path.join(genDir, 'units.json'), 'utf8'));

const recordings = [];
let skipped = 0;
for (const u of units) {
  const wav = readFileSync(path.join(genDir, 'audio', `${u.id}.wav`));
  const { samples, info } = core.decodeWavToFloat(wav);
  if (info.sampleRate !== 22050 || info.channels !== 1) {
    skipped++;
    continue;
  }
  // Each file is one isolated syllable, so the boundaries are exact: the whole file (edge silence is trimmed by the builder).
  recordings.push({
    id: u.id,
    wav,
    segments: [{ label: u.label, start: 0, end: samples.length, position: 'isolated' }],
  });
}
if (skipped) console.warn(`skipped ${skipped} files with the wrong format`);

const manifest = core.buildUnitDb({
  outDir: path.resolve(outDir),
  id: arg('--id', 'vi-north-vieneu'),
  name: gen.voiceName,
  locale: 'vi-VN',
  dialect: gen.dialect ?? 'northern',
  license: { id: gen.outputLicense, notes: gen.licenseNotes },
  datasetVersion: arg('--version', '1'),
  attribution: gen.attribution,
  recordingNotes: `Isolated syllables, ${gen.variants} variant(s) each, generated locally with ${gen.generator.name} ${gen.generator.version} (preset voice "${gen.voiceName}"); resampled to 22,050 Hz.`,
  provenance: {
    kind: 'ai-generated',
    generator: { ...gen.generator, localRun: true },
    notes: gen.notes,
  },
  recordings,
});
const db = core.UnitDb.load(path.resolve(outDir));
const bench = JSON.parse(
  readFileSync(path.resolve(import.meta.dirname, '../../config/vi-bench-syllables.json'), 'utf8'),
);
const report = core.buildDatasetReport(db, bench);
writeFileSync(path.join(path.resolve(outDir), 'dataset-report.json'), JSON.stringify(report, null, 2));
console.log(
  JSON.stringify(
    {
      id: manifest.id,
      units: manifest.units,
      distinctSyllables: report.distinctSyllables,
      corpus: report.corpus && { covered: report.corpus.covered, required: report.corpus.required },
      missingComponents: Object.fromEntries(
        Object.entries(report.components).map(([k, v]) => [k, v.missing]),
      ),
      provenance: report.provenance.kind,
      warnings: report.warnings,
    },
    null,
    2,
  ),
);
